/* ===== نظام الترجمات الشامل لحقبة كنعان (34 سؤال × 8 لغات) ===== */

const QUESTIONS_I18N = {
  ar: [
    {q:"من أول شعب سكن فلسطين وبنى حضارتها؟",o:["الكنعانيون","الرومان","العثمانيون"],f:"الكنعانيون هاجروا من الجزيرة العربية قبل 4000 سنة وبنوا أكثر من 200 مدينة في فلسطين.",h:"اسمهم يبدأ بحرف الكاف"},
    {q:"لماذا سميت فلسطين بأرض كنعان؟",o:["نسبةً للكنعانيين الذين سكنوها","نسبةً لجبل كنعان","نسبةً لنهر كنعان"],f:"سميت أرض كنعان نسبة إلى الكنعانيين الذين عمّروها وجعلوها جنة خضراء.",h:"الاسم مرتبط بالسكان الأوائل"},
    {q:"ما هي أقدم مدينة في فلسطين والعالم؟",o:["أريحا","القدس","غزة"],f:"أريحا أقدم مدينة مأهولة في التاريخ، بناها الكنعانيون وتسمى مدينة القمر.",h:"تقع في غور الأردن"},
    {q:"كم يقدّر عمر مدينة أريحا؟",o:["حوالي 10 آلاف سنة","حوالي 1000 سنة","حوالي 500 سنة"],f:"تل السلطان في أريحا يثبت أن عمرها 10,000 سنة، وفيها أقدم سور في العالم.",h:"أقدم من الأهرامات بكثير"},
    {q:"ماذا تعني كلمة كنعان؟",o:["الأرض المنخفضة وأرض الأرجوان","الأرض المرتفعة","الأرض الصحراوية"],f:"كنعان تعني الأرض المنخفضة، وأيضاً أرض الأرجوان لأنهم اشتهروا بصناعة اللون الأرجواني الثمين.",h:"لها معنيان مرتبطان بالطبيعة"},
    {q:"أين تقع فلسطين؟",o:["في قلب بلاد الشام وجنوب غرب آسيا","في شمال أفريقيا","في شرق أوروبا"],f:"موقع فلسطين استراتيجي يتوسط ثلاث قارات: آسيا وأفريقيا وأوروبا.",h:"في قلب العالم العربي"},
    {q:"ما عاصمة فلسطين؟",o:["القدس","رام الله","نابلس"],f:"القدس عاصمة فلسطين الأبدية، فيها المسجد الأقصى وكنيسة القيامة.",h:"أولى القبلتين"},
    {q:"ما اسم القدس الكنعاني القديم؟",o:["يبوس","أورشليم","إيليا"],f:"يبوس هو الاسم الكنعاني الأصلي للقدس نسبة لليبوسيين الكنعانيين الذين سكنوها.",h:"يبدأ بحرف الياء"},
    {q:"من بنى مدينة القدس أول مرة؟",o:["اليبوسيون الكنعانيون","الرومان","الإغريق"],f:"بنى اليبوسيون الكنعانيون القدس قبل 5000 سنة وجعلوها حصناً منيعاً.",h:"فرع من الكنعانيين"},
    {q:"ما البحر الذي يحدّ فلسطين غرباً؟",o:["البحر المتوسط","البحر الأحمر","بحر العرب"],f:"البحر المتوسط يعطي فلسطين ساحلاً جميلاً طوله 224 كم ومناخاً معتدلاً.",h:"نفس البحر الذي يطل على يافا وحيفا"},
    {q:"ما النهر الرئيسي في فلسطين؟",o:["نهر الأردن","نهر النيل","نهر الفرات"],f:"نهر الأردن ينبع من جبل الشيخ ويصب في البحر الميت وطوله 251 كم.",h:"يصب في البحر الميت"},
    {q:"ما مناخ فلسطين؟",o:["مناخ البحر المتوسط معتدل","مناخ صحراوي حار جداً","مناخ قطبي بارد"],f:"مناخ فلسطين متنوع: ساحل معتدل، جبل بارد شتاءً، وغور حار، وهذا سر غناها الزراعي.",h:"مثل مناخ لبنان"},
    {q:"اذكري 3 مدن كنعانية مشهورة ما زالت موجودة؟",o:["أريحا والقدس (يبوس) والخليل","لندن وباريس وروما","القاهرة وبغداد ودمشق فقط"],f:"أريحا، يبوس (القدس)، الخليل، نابلس، عكا، يافا، بيسان، مجدو - كلها كنعانية الأصل.",h:"مدن فلسطينية نعرفها اليوم"},
    {q:"بماذا اشتهر الكنعانيون في الزراعة؟",o:["زراعة القمح والزيتون والعنب","زراعة الأرز فقط","لم يهتموا بالزراعة"],f:"الكنعانيون أول من زرع الزيتون في العالم، وشجرة الزيتون رمز فلسطين حتى اليوم.",h:"ثلاثة محاصيل متوسطية مشهورة"},
    {q:"بماذا اشتهر الكنعانيون في الصناعة؟",o:["صناعة الأرجوان والزجاج والفخار","صناعة السيارات","صناعة البلاستيك"],f:"الأرجوان كان أغلى صبغة في العالم القديم، يستخرج من أصداف البحر ويصدر للملوك.",h:"صناعات يدوية قديمة ثمينة"},
    {q:"ماذا اخترع الكنعانيون وأهدوه للعالم؟",o:["الأبجدية / الكتابة الأبجدية","الإنترنت","الكهرباء"],f:"الأبجدية الكنعانية (22 حرفاً) هي أم كل أبجديات العالم، منها العربية والعبرية واللاتينية.",h:"اختراع ساعد البشرية على الكتابة بسهولة"},
    {q:"ما هي تضاريس فلسطين؟",o:["سهول ساحلية وجبال وغور وصحراء النقب","صحراء فقط","جبال جليدية فقط"],f:"في 27 ألف كم² تجد كل التضاريس: ساحل، جبل، غور، صحراء - فلسطين قارة مصغرة!",h:"متنوعة جداً رغم صغر المساحة"},
    {q:"ما هي بحيرة فلسطين المشهورة؟",o:["بحيرة طبريا","بحيرة فيكتوريا","بحيرة قارون"],f:"بحيرة طبريا عذبة وجميلة، تنخفض 212 م تحت سطح البحر وتغذي نهر الأردن.",h:"في شمال فلسطين"},
    {q:"ما هو البحر الميت؟",o:["أخفض نقطة في العالم وأكثرها ملوحة","بحر عادي مثل المتوسط","نهر كبير"],f:"البحر الميت -427 متر تحت سطح البحر، ملوحته 10 أضعاف البحر العادي ولا تعيش فيه أسماك.",h:"يمكنك أن تطفو على سطحه دون سباحة!"},
    {q:"لماذا فلسطين غنية زراعياً؟",o:["تنوع مناخها وتضاريسها وتربتها الخصبة","لأنها تستورد كل شيء","لأنها صحراء"],f:"من برتقال يافا إلى عنب الخليل وزيتون الجليل - تنوع المناخ جعل فلسطين سلة غذاء.",h:"السبب طبيعي جغرافي"},
    {q:"ما اللغة التي تكلمها الكنعانيون؟",o:["اللغة الكنعانية السامية القريبة من العربية","اللغة الإنجليزية","اللغة الصينية"],f:"الكنعانية قريبة جداً من العربية: كلمات مثل بيت، ملك، شمس، يم (بحر) ما زالت نفسها!",h:"من نفس عائلة اللغة العربية"},
    {q:"كيف كانت بيوت الكنعانيين؟",o:["من الطين والحجر بسقوف خشبية","من الحديد والزجاج","خيام فقط"],f:"بيوت الكنعانيين متينة من حجر وطين، بجدران سميكة تحمي من الحر والبرد، وبعضها ما زال قائماً!",h:"مواد طبيعية متوفرة في الجبل"},
    {q:"ما ديانة الكنعانيين؟",o:["وثنية يعبدون بعل وعشتار","مسلمون","مسيحيون"],f:"عبد الكنعانيون قوى الطبيعة: بعل إله المطر، وعشتار إلهة الخصب، قبل مجيء الديانات السماوية.",h:"قبل الإسلام والمسيحية"},
    {q:"ماذا بنى الكنعانيون للدفاع عن مدنهم؟",o:["أسوار عالية وأبراج مثل سور أريحا","خنادق مائية فقط","لم يبنوا شيئاً"],f:"سور أريحا عرضه 3 أمتار وارتفاعه 7 أمتار، أقدم وأقوى سور في التاريخ القديم.",h:"أريحا مشهورة بسورها"},
    {q:"لماذا فلسطين مطمع للغزاة عبر التاريخ؟",o:["موقعها الاستراتيجي بين القارات وطريق تجارة","لأنها فقيرة","لأنها جزيرة معزولة"],f:"فلسطين جسر بين آسيا وأفريقيا، وبوابة لمصر والشام والعراق، من يسيطر عليها يسيطر على التجارة.",h:"السبب جغرافي واقتصادي"},
    {q:"ما الأهمية الدينية لفلسطين؟",o:["مهد الديانات السماوية ومسري الرسول وأولى القبلتين","لا أهمية دينية لها","مهمة لديانة واحدة فقط"],f:"فيها الأقصى أولى القبلتين وثالث الحرمين، وكنيسة القيامة، والحرم الإبراهيمي - قلب العالم الروحي.",h:"مهمة للمسلمين والمسيحيين واليهود"},
    {q:"ما الأهمية التاريخية لفلسطين؟",o:["ممر للحضارات وملتقى طرق تجارية وثقافية","لم يمر بها أحد","كانت فارغة"],f:"كل جيوش وحضارات التاريخ مرت من فلسطين: طريق الحرير، طريق البخور، وطريق البحر.",h:"مثل سوق كبير يمر به الجميع"},
    {q:"ما الحضارات التي تعاقبت على فلسطين بعد الكنعانيين؟",o:["المصرية، الآشورية، البابلية، الفارسية، اليونانية، الرومانية","حضارة واحدة فقط","لم تأت حضارات بعدها"],f:"تعاقبت 24 حضارة على فلسطين، لكن الكنعانيين هم الأصل والأساس، والفلسطينيون اليوم امتدادهم.",h:"حضارات الشرق القديم كلها"},
    {q:"لماذا سمى اليونان الكنعانيين بالفينيقيين؟",o:["نسبة للأرجوان (phoinix) الذي صنعوه وصدّروه","نسبة لطائر الفينيق الأسطوري فقط","لأنهم سكنوا فينيقيا فقط"],f:"فينيق Phoinix باليونانية تعني الأرجواني، لأن الكنعانيين احتكروا صناعة اللون الأرجواني الملكي.",h:"الكلمة يونانية تعني اللون الأرجواني"},
    {q:"كيف حافظ الكنعانيون على هويتهم؟",o:["بالتمسك بأرضهم ولغتهم ومدنهم وزراعتهم","بالهجرة وترك الأرض","بالانصهار مع الغزاة"],f:"رغم الغزو، بقي الكنعانيون في أرضهم، يزرعونها ويبنونها - وهذا ما يفعله الفلسطيني اليوم: صمود!",h:"فكري في كلمة الصمود"},
    {q:"ما الدليل على قدم الحضارة في أريحا؟",o:["آثار تل السلطان وأسوارها وأبراجها الحجرية","لا يوجد دليل","كتابات حديثة فقط"],f:"تل السلطان في أريحا كشف بيوتاً وأسواراً وبرجاً حجرياً ارتفاعه 8 أمتار من 8000 سنة ق.م!",h:"تل أثري مشهور"},
    {q:"ماذا نتعلم من الكنعانيين اليوم؟",o:["حب الأرض والعمل والبناء والصمود","الكسل والهجرة","نسيان التاريخ"],f:"الكنعانيون علمونا: الأرض هي العرض، من يزرع أرضه لا يجوع، ومن يبني بيته لا يتشرد.",h:"قيم إيجابية للطالب"},
    {q:"ما علاقة الفلسطينيين اليوم بالكنعانيين؟",o:["امتداد تاريخي وحضاري وشعب واحد بأرض واحدة","لا علاقة بينهم","شعب مختلف تماماً"],f:"فحوصات الحمض النووي DNA تثبت أن 90% من الفلسطينيين هم أحفاد مباشرون للكنعانيين - نحن هنا منذ 4000 سنة!",h:"نحن أحفادهم"},
    {q:"لماذا ندرس تاريخ كنعان؟",o:["لنعرف جذورنا وحقنا التاريخي في فلسطين","للتسلية فقط","لأنه مادة غير مهمة"],f:"من لا يعرف تاريخه لا يعرف حقه. دراسة كنعان تثبت أن فلسطين لنا قبل أن يكتب التاريخ!",h:"لإثبات الحق التاريخي"}
  ],
  en: [
    {q:"Who was the first people to inhabit Palestine and build its civilization?",o:["Canaanites","Romans","Ottomans"],f:"The Canaanites migrated from the Arabian Peninsula 4000 years ago and built more than 200 cities in Palestine.",h:"Their name starts with the letter C"},
    {q:"Why was Palestine called the Land of Canaan?",o:["Named after the Canaanites who settled it","Named after Mount Canaan","Named after the Canaan River"],f:"The land was named Canaan after the Canaanites who developed it and made it a green paradise.",h:"The name is related to the first inhabitants"},
    {q:"What is the oldest city in Palestine and the world?",o:["Jericho","Jerusalem","Gaza"],f:"Jericho is the oldest inhabited city in history, built by the Canaanites and called the City of the Moon.",h:"Located in the Jordan Valley"},
    {q:"How old is the city of Jericho estimated to be?",o:["About 10,000 years","About 1,000 years","About 500 years"],f:"Tel es-Sultan in Jericho proves it is 10,000 years old and contains the oldest wall in the world.",h:"Much older than the pyramids"},
    {q:"What does the word Canaan mean?",o:["The lowland and the land of purple","The highland","The desert land"],f:"Canaan means the lowland, and also the land of purple because they were famous for making precious purple dye.",h:"It has two meanings related to nature"},
    {q:"Where is Palestine located?",o:["In the heart of the Levant and Southwest Asia","In North Africa","In Eastern Europe"],f:"Palestine's location is strategic, positioned between three continents: Asia, Africa, and Europe.",h:"In the heart of the Arab world"},
    {q:"What is the capital of Palestine?",o:["Jerusalem","Ramallah","Nablus"],f:"Jerusalem is the eternal capital of Palestine, containing the Al-Aqsa Mosque and the Church of the Holy Sepulchre.",h:"The first direction of prayer"},
    {q:"What was the ancient Canaanite name of Jerusalem?",o:["Jebus","Jerusalem","Aelia"],f:"Jebus was the original Canaanite name for Jerusalem, named after the Jebusites, a Canaanite people who settled it.",h:"Starts with the letter J"},
    {q:"Who built the city of Jerusalem for the first time?",o:["The Jebusite Canaanites","The Romans","The Greeks"],f:"The Jebusite Canaanites built Jerusalem 5000 years ago and made it a formidable fortress.",h:"A branch of the Canaanites"},
    {q:"Which sea borders Palestine to the west?",o:["The Mediterranean Sea","The Red Sea","The Arabian Sea"],f:"The Mediterranean Sea gives Palestine a beautiful coastline 224 km long and a moderate climate.",h:"The same sea that overlooks Jaffa and Haifa"},
    {q:"What is the main river in Palestine?",o:["The Jordan River","The Nile River","The Euphrates River"],f:"The Jordan River originates from Mount Hermon and flows into the Dead Sea with a length of 251 km.",h:"It flows into the Dead Sea"},
    {q:"What is the climate of Palestine?",o:["Mediterranean climate that is moderate","Very hot desert climate","Cold polar climate"],f:"Palestine's climate is diverse: moderate coast, cold mountains in winter, hot valleys - this is the secret of its agricultural wealth.",h:"Like the climate of Lebanon"},
    {q:"Name 3 famous Canaanite cities still existing today?",o:["Jericho, Jerusalem (Jebus), and Hebron","London, Paris, and Rome","Cairo, Baghdad, and Damascus only"],f:"Jericho, Jebus (Jerusalem), Hebron, Nablus, Acre, Jaffa, Bethshan, Megiddo - all are of Canaanite origin.",h:"Palestinian cities we know today"},
    {q:"What were the Canaanites famous for in agriculture?",o:["Growing wheat, olives, and grapes","Growing rice only","They didn't care about agriculture"],f:"The Canaanites were the first to plant olives in the world, and the olive tree is a symbol of Palestine even today.",h:"Three famous Mediterranean crops"},
    {q:"What were the Canaanites famous for in industry?",o:["Manufacturing purple dye, glass, and pottery","Manufacturing cars","Manufacturing plastic"],f:"Purple was the most expensive dye in the ancient world, extracted from seashells and exported to kings.",h:"Ancient precious handicrafts"},
    {q:"What did the Canaanites invent and give to the world?",o:["The alphabet / alphabetic writing","The Internet","Electricity"],f:"The Canaanite alphabet (22 letters) is the mother of all alphabets in the world, including Arabic, Hebrew, and Latin.",h:"An invention that helped humanity write easily"},
    {q:"What are the geographical features of Palestine?",o:["Coastal plains, mountains, valleys, and the Negev desert","Only desert","Only glacial mountains"],f:"In 27,000 km² you find all geographical features: coast, mountain, valley, desert - Palestine is a miniature continent!",h:"Very diverse despite its small size"},
    {q:"What is Palestine's famous lake?",o:["Lake Tiberias (Sea of Galilee)","Lake Victoria","Lake Qarun"],f:"Lake Tiberias is fresh and beautiful, situated 212 m below sea level and feeds the Jordan River.",h:"In northern Palestine"},
    {q:"What is the Dead Sea?",o:["The lowest point on Earth and most salty","An ordinary sea like the Mediterranean","A large river"],f:"The Dead Sea is 427 meters below sea level, ten times saltier than ordinary seawater with no fish living in it.",h:"You can float on its surface without swimming!"},
    {q:"Why is Palestine rich in agriculture?",o:["Diversity of its climate, terrain, and fertile soil","Because it imports everything","Because it's a desert"],f:"From Jaffa oranges to Hebron grapes to Galilee olives - climate diversity made Palestine a food basket.",h:"The reason is geographical and natural"},
    {q:"What language did the Canaanites speak?",o:["Canaanite Semitic language, similar to Arabic","English","Chinese"],f:"Canaanite is very close to Arabic: words like house, king, sun, yam (sea) are still the same!",h:"From the same language family as Arabic"},
    {q:"What were Canaanite houses like?",o:["Made of clay and stone with wooden roofs","Made of iron and glass","Only tents"],f:"Canaanite houses were sturdy, made of stone and clay with thick walls protecting from heat and cold, and some still stand!",h:"Natural materials available in the mountains"},
    {q:"What was the religion of the Canaanites?",o:["Pagan, worshipping Baal and Astarte","Muslim","Christian"],f:"The Canaanites worshipped forces of nature: Baal the god of rain, and Astarte the goddess of fertility, before the arrival of Abrahamic religions.",h:"Before Islam and Christianity"},
    {q:"What did the Canaanites build to defend their cities?",o:["High walls and towers like the wall of Jericho","Water trenches only","They built nothing"],f:"The wall of Jericho was 3 meters wide and 7 meters high, the oldest and strongest wall in ancient history.",h:"Jericho is famous for its wall"},
    {q:"Why was Palestine coveted by invaders throughout history?",o:["Its strategic location between continents and trade routes","Because it's poor","Because it's an isolated island"],f:"Palestine is a bridge between Asia and Africa, and a gateway to Egypt, the Levant, and Iraq - whoever controls it controls trade.",h:"The reason is geographical and economic"},
    {q:"What is the religious importance of Palestine?",o:["Cradle of monotheistic religions and the first direction of prayer","No religious importance","Important to only one religion"],f:"It contains Al-Aqsa the first direction of prayer and third holiest site, Church of the Holy Sepulchre, and Ibrahimi Mosque - the spiritual center of the world.",h:"Important to Muslims, Christians, and Jews"},
    {q:"What is the historical importance of Palestine?",o:["A passage for civilizations and a meeting point of trade and cultural routes","No one passed through it","It was empty"],f:"Every army and civilization of history passed through Palestine: Silk Road, Spice Route, and sea routes.",h:"Like a big market that everyone passes through"},
    {q:"Which civilizations succeeded the Canaanites in Palestine?",o:["Egyptian, Assyrian, Babylonian, Persian, Greek, Roman","Only one civilization","No civilizations came after"],f:"24 civilizations succeeded each other in Palestine, but the Canaanites are the origin and foundation, and Palestinians today are their continuation.",h:"All ancient civilizations of the Middle East"},
    {q:"Why did the Greeks call the Canaanites Phoenicians?",o:["Named after the purple (phoinix) they made and exported","Named after the mythical Phoenix bird only","Because they only lived in Phoenicia"],f:"Phoinix in Greek means purple, because the Canaanites monopolized the production of the precious royal purple dye.",h:"The word is Greek meaning the purple color"},
    {q:"How did the Canaanites preserve their identity?",o:["By clinging to their land, language, cities, and agriculture","By emigration and abandoning the land","By assimilating with invaders"],f:"Despite invasion, the Canaanites remained on their land, farming and building it - this is what Palestinians do today: steadfastness!",h:"Think about the word steadfastness"},
    {q:"What is the evidence of ancient civilization in Jericho?",o:["Remains of Tel es-Sultan, walls, and stone towers","No evidence","Only recent writings"],f:"Tel es-Sultan in Jericho revealed houses, walls, and a stone tower 8 meters high from 8000 BCE!",h:"A famous archaeological mound"},
    {q:"What do we learn from the Canaanites today?",o:["Love of land, work, building, and steadfastness","Laziness and emigration","Forgetting history"],f:"The Canaanites taught us: the land is honor, whoever farms his land will not starve, whoever builds his house will not be displaced.",h:"Positive values for students"},
    {q:"What is the relationship of Palestinians today to the Canaanites?",o:["A historical and cultural continuation and one people in one land","No relationship","A completely different people"],f:"DNA tests prove that 90% of Palestinians are direct descendants of the Canaanites - we have been here for 4000 years!",h:"We are their descendants"},
    {q:"Why do we study the history of Canaan?",o:["To know our roots and historical rights in Palestine","For entertainment only","Because it's an unimportant subject"],f:"Whoever doesn't know his history doesn't know his rights. Studying Canaan proves Palestine is ours before history was even written!",h:"To prove our historical rights"}
  ],
  fr: [
    {q:"Quel était le premier peuple à habiter la Palestine et à construire sa civilisation?",o:["Les Cananéens","Les Romains","Les Ottomans"],f:"Les Cananéens ont migré de la Péninsule arabique il y a 4000 ans et ont construit plus de 200 villes en Palestine.",h:"Leur nom commence par la lettre K"},
    {q:"Pourquoi la Palestine s'appelait-elle Terre de Canaan?",o:["D'après les Cananéens qui l'ont peuplée","D'après le Mont Canaan","D'après le Fleuve Canaan"],f:"La terre a été nommée Canaan d'après les Cananéens qui l'ont développée et en ont fait un paradis verdoyant.",h:"Le nom est lié aux premiers habitants"},
    {q:"Quelle est la plus ancienne ville de Palestine et du monde?",o:["Jéricho","Jérusalem","Gaza"],f:"Jéricho est la plus ancienne ville habitée de l'histoire, construite par les Cananéens et appelée la Cité de la Lune.",h:"Située dans la vallée du Jourdain"},
    {q:"Quel âge est estimé pour la ville de Jéricho?",o:["Environ 10 000 ans","Environ 1 000 ans","Environ 500 ans"],f:"Tell es-Sultan à Jéricho prouve qu'elle a 10 000 ans et contient le plus ancien mur du monde.",h:"Beaucoup plus ancienne que les pyramides"},
    {q:"Que signifie le mot Canaan?",o:["La terre basse et la terre de pourpre","La terre haute","La terre désertique"],f:"Canaan signifie la terre basse, et aussi la terre de pourpre car ils étaient célèbres pour fabriquer la teinture pourpre précieuse.",h:"Il a deux significations liées à la nature"},
    {q:"Où se trouve la Palestine?",o:["Au cœur du Levant et du sud-ouest de l'Asie","En Afrique du Nord","En Europe de l'Est"],f:"La location de la Palestine est stratégique, positionnée entre trois continents: l'Asie, l'Afrique et l'Europe.",h:"Au cœur du monde arabe"},
    {q:"Quelle est la capitale de la Palestine?",o:["Jérusalem","Ramallah","Naplouse"],f:"Jérusalem est la capitale éternelle de la Palestine, contenant la Mosquée Al-Aqsa et l'Église du Saint-Sépulcre.",h:"La première direction de prière"},
    {q:"Quel était le nom cananéen ancien de Jérusalem?",o:["Jébus","Jérusalem","Aelia"],f:"Jébus était le nom cananéen original de Jérusalem, nommé d'après les Jébusites, un peuple cananéen qui l'habitait.",h:"Commence par la lettre J"},
    {q:"Qui a construit la ville de Jérusalem pour la première fois?",o:["Les Cananéens Jébusites","Les Romains","Les Grecs"],f:"Les Cananéens Jébusites ont construit Jérusalem il y a 5000 ans et en ont fait une forteresse redoutable.",h:"Une branche des Cananéens"},
    {q:"Quel est la mer qui borde la Palestine à l'ouest?",o:["La Mer Méditerranée","La Mer Rouge","La Mer d'Arabie"],f:"La Méditerranée donne à la Palestine un magnifique littoral de 224 km de long et un climat modéré.",h:"La même mer qui domine Jaffa et Haïfa"},
    {q:"Quel est le fleuve principal de la Palestine?",o:["Le Fleuve Jourdain","Le Fleuve Nil","Le Fleuve Euphrate"],f:"Le Jourdain prend sa source au Mont Hermon et se jette dans la Mer Morte avec une longueur de 251 km.",h:"Il se jette dans la Mer Morte"},
    {q:"Quel est le climat de la Palestine?",o:["Climat méditerranéen modéré","Climat désertique très chaud","Climat polaire froid"],f:"Le climat de la Palestine est diversifié: côtes modérées, montagnes froides en hiver, vallées chaudes - c'est le secret de sa richesse agricole.",h:"Comme le climat du Liban"},
    {q:"Nommez 3 villes cananéennes célèbres qui existent toujours?",o:["Jéricho, Jérusalem (Jébus) et Hébron","Londres, Paris et Rome","Le Caire, Bagdad et Damas uniquement"],f:"Jéricho, Jébus (Jérusalem), Hébron, Naplouse, Acre, Jaffa, Bethshan, Megiddo - toutes sont d'origine cananéenne.",h:"Des villes palestiniennes que nous connaissons"},
    {q:"Pour quoi les Cananéens étaient-ils célèbres en agriculture?",o:["Cultiver le blé, les olives et les raisins","Cultiver le riz seulement","Ils ne s'occupaient pas d'agriculture"],f:"Les Cananéens ont été les premiers à planter des oliviers au monde, et l'olivier est un symbole de la Palestine aujourd'hui.",h:"Trois cultures méditerranéennes célèbres"},
    {q:"Pour quoi les Cananéens étaient-ils célèbres en industrie?",o:["Fabriquer la teinture pourpre, le verre et la poterie","Fabriquer des voitures","Fabriquer du plastique"],f:"La pourpre était la teinture la plus chère du monde ancien, extraite des coquillages et exportée aux rois.",h:"Des métiers anciens précieux"},
    {q:"Qu'ont inventé les Cananéens et donné au monde?",o:["L'alphabet / l'écriture alphabétique","Internet","L'électricité"],f:"L'alphabet cananéen (22 lettres) est la mère de tous les alphabets du monde, y compris l'arabe, l'hébreu et le latin.",h:"Une invention qui a aidé l'humanité à écrire facilement"},
    {q:"Quelles sont les caractéristiques géographiques de la Palestine?",o:["Plaines côtières, montagnes, vallées et désert du Néguev","Seulement désert","Seulement montagnes glaciaires"],f:"En 27 000 km² vous trouvez tous les reliefs: côte, montagne, vallée, désert - la Palestine est un continent en miniature!",h:"Très diversifiée malgré sa petite taille"},
    {q:"Quel est le lac célèbre de la Palestine?",o:["Lac de Tibériade (Mer de Galilée)","Lac Victoria","Lac Qarun"],f:"Le Lac de Tibériade est douce et belle, situated 212 m au-dessous du niveau des mers et alimente le Jourdain.",h:"En Palestin septentrionale"},
    {q:"Qu'est-ce que la Mer Morte?",o:["Le point le plus bas sur Terre et le plus salé","Une mer ordinaire comme la Méditerranée","Un grand fleuve"],f:"La Mer Morte est à 427 mètres au-dessous du niveau des mers, dix fois plus salée que l'eau de mer ordinaire sans poissons.",h:"Vous pouvez flotter à sa surface sans nager!"},
    {q:"Pourquoi la Palestine est-elle riche en agriculture?",o:["La diversité de son climat, terrain et sol fertile","Parce qu'elle importe tout","Parce que c'est un désert"],f:"Des oranges de Jaffa aux raisins de Hébron au oliviers de Galilée - la diversité climatique a fait de la Palestine un grenier alimentaire.",h:"La raison est géographique et naturelle"},
    {q:"Quelle langue parlaient les Cananéens?",o:["La langue cananéenne sémitique, similaire à l'arabe","L'anglais","Le chinois"],f:"Le cananéen est très proche de l'arabe: des mots comme maison, roi, soleil, yam (mer) sont toujours les mêmes!",h:"De la même famille de langue que l'arabe"},
    {q:"Comment étaient les maisons des Cananéens?",o:["Faites d'argile et pierre avec toits en bois","Faites de fer et verre","Seulement des tentes"],f:"Les maisons cananéennes étaient robustes, en pierre et argile avec des murs épais protégeant du froid et la chaleur, et quelques-unes subsistent!",h:"Des matériaux naturels disponibles en montagne"},
    {q:"Quelle était la religion des Cananéens?",o:["Païenne, adorant Baal et Astarté","Musulmane","Chrétienne"],f:"Les Cananéens adoraient les forces de la nature: Baal le dieu de la pluie et Astarté la déesse de la fertilité, avant l'arrivée des religions abrahamiques.",h:"Avant l'islam et le christianisme"},
    {q:"Que construisirent les Cananéens pour défendre leurs villes?",o:["Des murs élevés et des tours comme le mur de Jéricho","Des tranchées d'eau seulement","Ils ne construisirent rien"],f:"Le mur de Jéricho faisait 3 mètres de large et 7 mètres de haut, le plus ancien et le plus robuste mur de l'histoire ancienne.",h:"Jéricho est célèbre pour son mur"},
    {q:"Pourquoi la Palestine était-elle convoitée par les envahisseurs au cours de l'histoire?",o:["Son localisation stratégique entre continents et les routes commerciales","Parce qu'elle est pauvre","Parce que c'est une île isolée"],f:"La Palestine est un pont entre l'Asie et l'Afrique, et une porte vers l'Égypte, le Levant et l'Irak - qui la contrôle contrôle le commerce.",h:"La raison est géographique et économique"},
    {q:"Quelle est l'importance religieuse de la Palestine?",o:["Berceau des religions monothéistes et première direction de prière","Aucune importance religieuse","Importante pour une seule religion"],f:"Elle contient Al-Aqsa la première direction de prière et le troisième site le plus saint, l'Église du Saint-Sépulcre, et la Mosquée Ibrahimi - le centre spirituel du monde.",h:"Important pour les musulmans, chrétiens et juifs"},
    {q:"Quelle est l'importance historique de la Palestine?",o:["Un passage pour les civilisations et un point de rencontre des routes commerciales et culturelles","Personne ne l'a traversée","Elle était vide"],f:"Chaque armée et civilisation de l'histoire a traversé la Palestine: Route de la Soie, Route des Épices et routes maritimes.",h:"Comme un grand marché par lequel chacun passe"},
    {q:"Quelles civilisations ont succédé aux Cananéens en Palestine?",o:["Égyptienne, assyrienne, babylonienne, perse, grecque, romaine","Une seule civilisation","Aucune civilisation ne les a suivis"],f:"24 civilisations se sont succédé en Palestine, mais les Cananéens sont l'origine et le fondement, et les Palestiniens d'aujourd'hui en sont la continuation.",h:"Toutes les anciennes civilisations du Moyen-Orient"},
    {q:"Pourquoi les Grecs appelaient-ils les Cananéens Phéniciens?",o:["D'après la pourpre (phoinix) qu'ils fabriquaient et exportaient","D'après l'oiseau mythique Phénix seulement","Parce qu'ils vivaient seulement en Phénicie"],f:"Phoinix en grec signifie pourpre, car les Cananéens monopolisaient la production de la précieuse teinture pourpre royale.",h:"Le mot est grec signifiant la couleur pourpre"},
    {q:"Comment les Cananéens ont-ils préservé leur identité?",o:["En s'accrochant à leur terre, langue, villes et agriculture","Par l'émigration et l'abandon de la terre","Par l'assimilation avec les envahisseurs"],f:"Malgré l'invasion, les Cananéens sont restés sur leur terre, la cultivant et la construisant - c'est ce que les Palestiniens font aujourd'hui: la résistance!",h:"Pensez au mot résistance"},
    {q:"Quelles sont les preuves de la civilisation ancienne à Jéricho?",o:["Vestiges de Tell es-Sultan, murs et tours en pierre","Aucune preuve","Seulement des écrits récents"],f:"Tell es-Sultan à Jéricho a révélé des maisons, des murs et une tour en pierre de 8 mètres de haut de 8000 av.J-C!",h:"Un tell archéologique célèbre"},
    {q:"Que tirons-nous des Cananéens aujourd'hui?",o:["L'amour de la terre, du travail, de la construction et de la résistance","La paresse et l'émigration","L'oubli de l'histoire"],f:"Les Cananéens nous ont enseigné: la terre est l'honneur, celui qui cultive sa terre ne mourra pas de faim, celui qui construit sa maison ne sera pas déplacé.",h:"Des valeurs positives pour les étudiants"},
    {q:"Quelle est la relation des Palestiniens d'aujourd'hui avec les Cananéens?",o:["Une continuation historique et culturelle et un peuple dans une terre","Aucune relation","Un peuple complètement différent"],f:"Les tests ADN prouvent que 90% des Palestiniens sont des descendants directs des Cananéens - nous sommes ici depuis 4000 ans!",h:"Nous sommes leurs descendants"},
    {q:"Pourquoi étudions-nous l'histoire de Canaan?",o:["Pour connaître nos racines et nos droits historiques en Palestine","Pour le divertissement seulement","Parce que c'est un sujet sans importance"],f:"Celui qui ne connaît pas son histoire ne connaît pas ses droits. Étudier Canaan prouve que la Palestine est la nôtre avant même l'écriture de l'histoire!",h:"Pour prouver nos droits historiques"}
  ],
  es: [
    {q:"¿Quién fue el primer pueblo en habitar Palestina y construir su civilización?",o:["Los cananeos","Los romanos","Los otomanos"],f:"Los cananeos emigraron de la Península Arábiga hace 4000 años y construyeron más de 200 ciudades en Palestina.",h:"Su nombre comienza con la letra C"},
    {q:"¿Por qué se llamaba Palestina Tierra de Canaán?",o:["Por los cananeos que la poblaron","Por el Monte Canaán","Por el Río Canaán"],f:"La tierra fue nombrada Canaán por los cananeos que la desarrollaron e hicieron un paraíso verde.",h:"El nombre está relacionado con los primeros habitantes"},
    {q:"¿Cuál es la ciudad más antigua de Palestina y del mundo?",o:["Jericó","Jerusalén","Gaza"],f:"Jericó es la ciudad habitada más antigua de la historia, construida por los cananeos y llamada la Ciudad de la Luna.",h:"Ubicada en el Valle del Jordán"},
    {q:"¿Cuál se estima que es la edad de la ciudad de Jericó?",o:["Alrededor de 10,000 años","Alrededor de 1,000 años","Alrededor de 500 años"],f:"Tell es-Sultan en Jericó prueba que tiene 10,000 años y contiene el muro más antiguo del mundo.",h:"Mucho más antiguo que las pirámides"},
    {q:"¿Qué significa la palabra Canaán?",o:["La tierra baja y la tierra de púrpura","La tierra alta","La tierra desértica"],f:"Canaán significa la tierra baja, y también la tierra de púrpura porque eran famosos por hacer tinte púrpura precioso.",h:"Tiene dos significados relacionados con la naturaleza"},
    {q:"¿Dónde se encuentra Palestina?",o:["En el corazón del Levante y el suroeste de Asia","En el norte de África","En el este de Europa"],f:"La ubicación de Palestina es estratégica, ubicada entre tres continentes: Asia, África y Europa.",h:"En el corazón del mundo árabe"},
    {q:"¿Cuál es la capital de Palestina?",o:["Jerusalén","Ramallah","Nablús"],f:"Jerusalén es la capital eterna de Palestina, con la Mezquita Al-Aqsa e la Iglesia del Santo Sepulcro.",h:"La primera dirección de oración"},
    {q:"¿Cuál era el nombre cananeo antiguo de Jerusalén?",o:["Jebús","Jerusalén","Aelia"],f:"Jebús era el nombre cananeo original de Jerusalén, nombrado por los jebuseos, un pueblo cananeo que la habitaba.",h:"Comienza con la letra J"},
    {q:"¿Quién construyó la ciudad de Jerusalén por primera vez?",o:["Los cananeos jebuseos","Los romanos","Los griegos"],f:"Los cananeos jebuseos construyeron Jerusalén hace 5000 años e hicieron de ella una fortaleza formidable.",h:"Una rama de los cananeos"},
    {q:"¿Cuál es el mar que bordea Palestina al oeste?",o:["El Mar Mediterráneo","El Mar Rojo","El Mar de Arabia"],f:"El Mediterráneo le da a Palestina una hermosa costa de 224 km de largo y un clima moderado.",h:"El mismo mar que domina Jaffa y Haifa"},
    {q:"¿Cuál es el río principal de Palestina?",o:["El Río Jordán","El Río Nilo","El Río Éufrates"],f:"El Jordán nace en el Monte Hermón y desemboca en el Mar Muerto con una longitud de 251 km.",h:"Desemboca en el Mar Muerto"},
    {q:"¿Cuál es el clima de Palestina?",o:["Clima mediterráneo moderado","Clima desértico muy caluroso","Clima polar frío"],f:"El clima de Palestina es diverso: costa moderada, montañas frías en invierno, valles calurosos - este es el secreto de su riqueza agrícola.",h:"Como el clima del Líbano"},
    {q:"¿Nombre 3 ciudades cananeas famosas que aún existen?",o:["Jericó, Jerusalén (Jebús) y Hebrón","Londres, París y Roma","El Cairo, Bagdad y Damasco solamente"],f:"Jericó, Jebús (Jerusalén), Hebrón, Nablús, Acre, Jaffa, Bethshan, Meguido - todas son de origen cananeo.",h:"Ciudades palestinas que conocemos"},
    {q:"¿Por qué eran famosos los cananeos en agricultura?",o:["Cultivar trigo, olivas y uvas","Cultivar solo arroz","No se preocupaban por la agricultura"],f:"Los cananeos fueron los primeros en plantar olivos en el mundo, y el olivo es un símbolo de Palestina hoy en día.",h:"Tres cultivos mediterráneos famosos"},
    {q:"¿Por qué eran famosos los cananeos en industria?",o:["Fabricar tinte púrpura, vidrio y cerámica","Fabricar coches","Fabricar plástico"],f:"La púrpura era el tinte más caro del mundo antiguo, extraído de conchas marinas y exportado a reyes.",h:"Artesanías antiguas preciosas"},
    {q:"¿Qué inventaron los cananeos y dieron al mundo?",o:["El alfabeto / la escritura alfabética","Internet","La electricidad"],f:"El alfabeto cananeo (22 letras) es la madre de todos los alfabetos del mundo, incluidos árabe, hebreo y latín.",h:"Un invento que ayudó a la humanidad a escribir fácilmente"},
    {q:"¿Cuáles son las características geográficas de Palestina?",o:["Llanuras costeras, montañas, valles y el desierto del Néguev","Solo desierto","Solo montañas glaciares"],f:"En 27,000 km² encuentras todos los relieves: costa, montaña, valle, desierto - ¡Palestina es un continente en miniatura!",h:"Muy diversa a pesar de su pequeño tamaño"},
    {q:"¿Cuál es el lago famoso de Palestina?",o:["Lago de Tiberíades (Mar de Galilea)","Lago Victoria","Lago Qarun"],f:"El Lago de Tiberíades es fresco y hermoso, a 212 m bajo el nivel del mar y alimenta el Río Jordán.",h:"En el norte de Palestina"},
    {q:"¿Qué es el Mar Muerto?",o:["El punto más bajo en la Tierra y el más salado","Un mar ordinario como el Mediterráneo","Un gran río"],f:"El Mar Muerto está 427 metros bajo el nivel del mar, diez veces más salado que el agua de mar ordinaria sin peces.",h:"¡Puedes flotar en su superficie sin nadar!"},
    {q:"¿Por qué Palestina es rica en agricultura?",o:["Diversidad de su clima, terreno y suelo fértil","Porque importa todo","Porque es un desierto"],f:"Desde naranjas de Jaffa a uvas de Hebrón a olivos de Galilea - la diversidad climática hizo de Palestina un granero de alimentos.",h:"La razón es geográfica y natural"},
    {q:"¿Qué idioma hablaban los cananeos?",o:["La lengua cananea semítica, similar al árabe","Inglés","Chino"],f:"El cananeo es muy cercano al árabe: palabras como casa, rey, sol, yam (mar) siguen siendo las mismas!",h:"De la misma familia de idiomas que el árabe"},
    {q:"¿Cómo eran las casas de los cananeos?",o:["Hechas de arcilla y piedra con techos de madera","Hechas de hierro y vidrio","Solo tiendas"],f:"Las casas cananeas eran robustas, de piedra y arcilla con paredes gruesas que protegían del calor y del frío, ¡y algunas aún se mantienen!",h:"Materiales naturales disponibles en las montañas"},
    {q:"¿Cuál era la religión de los cananeos?",o:["Pagana, adorando a Baal y Astarté","Musulmana","Cristiana"],f:"Los cananeos adoraban fuerzas de la naturaleza: Baal el dios de la lluvia y Astarté la diosa de la fertilidad, antes de la llegada de las religiones abrahámicas.",h:"Antes del islam y el cristianismo"},
    {q:"¿Qué construyeron los cananeos para defender sus ciudades?",o:["Muros altos y torres como el muro de Jericó","Solo trincheras de agua","No construyeron nada"],f:"El muro de Jericó tenía 3 metros de ancho y 7 metros de alto, el muro más antiguo y más fuerte de la historia antigua.",h:"Jericó es famosa por su muro"},
    {q:"¿Por qué Palestina fue codiciada por invasores a lo largo de la historia?",o:["Su ubicación estratégica entre continentes y rutas comerciales","Porque es pobre","Porque es una isla aislada"],f:"Palestina es un puente entre Asia y África, y una puerta a Egipto, el Levante e Irak - quien la controla controla el comercio.",h:"La razón es geográfica y económica"},
    {q:"¿Cuál es la importancia religiosa de Palestina?",o:["Cuna de religiones monoteístas y primera dirección de oración","Sin importancia religiosa","Importante para una sola religión"],f:"Contiene Al-Aqsa la primera dirección de oración y el tercer sitio más santo, Iglesia del Santo Sepulcro, Mezquita Ibrahimí - el centro espiritual del mundo.",h:"Importante para musulmanes, cristianos y judíos"},
    {q:"¿Cuál es la importancia histórica de Palestina?",o:["Un paso para civilizaciones y un punto de encuentro de rutas comerciales y culturales","Nadie pasó por ella","Estaba vacía"],f:"Todo ejército y civilización de la historia pasó por Palestina: Ruta de la Seda, Ruta de las Especias y rutas marítimas.",h:"Como un gran mercado por el que todos pasan"},
    {q:"¿Qué civilizaciones sucedieron a los cananeos en Palestina?",o:["Egipcia, asiria, babilónica, persa, griega, romana","Solo una civilización","Ninguna civilización después"],f:"24 civilizaciones se sucedieron en Palestina, pero los cananeos son el origen y el fundamento, y los palestinos de hoy son su continuación.",h:"Todas las antiguas civilizaciones de Oriente Medio"},
    {q:"¿Por qué los griegos llamaban fenicios a los cananeos?",o:["Nombrados por la púrpura (phoinix) que hacían y exportaban","Nombrados por el pájaro mitológico Fénix solamente","Porque solo vivían en Fenicia"],f:"Phoinix en griego significa púrpura, porque los cananeos monopolizaban la producción del precioso tinte púrpura real.",h:"La palabra es griega que significa el color púrpura"},
    {q:"¿Cómo preservaron su identidad los cananeos?",o:["Aferrándose a su tierra, lengua, ciudades y agricultura","Por emigración y abandono de la tierra","Por asimilación con invasores"],f:"A pesar de la invasión, los cananeos permanecieron en su tierra, cultivándola y construyéndola - esto es lo que los palestinos hacen hoy: resistencia!",h:"Piensa en la palabra resistencia"},
    {q:"¿Cuál es la evidencia de civilización antigua en Jericó?",o:["Restos de Tell es-Sultan, muros y torres de piedra","Sin evidencia","Solo escritos recientes"],f:"Tell es-Sultan en Jericó reveló casas, muros y una torre de piedra de 8 metros de altura de 8000 a.C.!",h:"Un tell arqueológico famoso"},
    {q:"¿Qué aprendemos de los cananeos hoy?",o:["Amor por la tierra, trabajo, construcción y resistencia","Pereza y emigración","Olvido de la historia"],f:"Los cananeos nos enseñaron: la tierra es honor, quien cultiva su tierra no morirá de hambre, quien construye su casa no será desplazado.",h:"Valores positivos para estudiantes"},
    {q:"¿Cuál es la relación de los palestinos de hoy con los cananeos?",o:["Una continuación histórica y cultural y un pueblo en una tierra","Sin relación","Un pueblo completamente diferente"],f:"Las pruebas de ADN prueban que el 90% de los palestinos son descendientes directos de los cananeos - ¡hemos estado aquí durante 4000 años!",h:"Somos sus descendientes"},
    {q:"¿Por qué estudiamos la historia de Canaán?",o:["Para conocer nuestras raíces y derechos históricos en Palestina","Solo para entretenimiento","Porque es un tema sin importancia"],f:"Quien no conoce su historia no conoce sus derechos. Estudiar Canaán prueba que Palestina es nuestra ¡incluso antes de que se escribiera la historia!",h:"Para probar nuestros derechos históricos"}
  ],

  sv: [
    {q:"Vem var det första folket att bosätta sig i Palestina och bygga sin civilisation?",o:["Kananéerna","Romarna","Ottomanerna"],f:"Kananéerna migrerade från Arabiska halvön för 4000 år sedan och byggde mer än 200 städer i Palestina.",h:"Deras namn börjar med bokstaven C"},
    {q:"Varför kallades Palestina för Kanaans land?",o:["Efter kananéerna som bosatte sig där","Efter berget Kanaan","Efter floden Kanaan"],f:"Landet kallades Kanaan efter kananéerna som utvecklade det och gjorde det till ett grönt paradis.",h:"Namnet är relaterat till de första invånarna"},
    {q:"Vad är den äldsta staden i Palestina och världen?",o:["Jeriko","Jerusalem","Gaza"],f:"Jeriko är den äldsta bebodda staden i historien, byggd av kananéerna och kallas Månens stad.",h:"Belägen i Jordandalen"},
    {q:"Hur gammal uppskattas staden Jeriko vara?",o:["Cirka 10 000 år","Cirka 1 000 år","Cirka 500 år"],f:"Tell es-Sultan i Jeriko bevisar att den är 10 000 år gammal och innehåller världens äldsta vägg.",h:"Mycket äldre än pyramiderna"},
    {q:"Vad betyder ordet Kanaan?",o:["Lågland och purpurland","Högland","Ökenland"],f:"Kanaan betyder lågland och också purpurland eftersom de var berömda för att tillverka dyr purpurfärg.",h:"Det har två betydelser relaterade till naturen"},
    {q:"Var är Palestina beläget?",o:["I hjärtat av Levanten och sydvästra Asien","I Nordafrika","I Östeuropa"],f:"Palestinas läge är strategiskt, beläget mellan tre kontinenter: Asien, Afrika och Europa.",h:"I hjärtat av den arabiska världen"},
    {q:"Vad är huvudstaden i Palestina?",o:["Jerusalem","Ramallah","Nablus"],f:"Jerusalem är Palestinas eviga huvudstad, innehållande Al-Aqsa-moskén och Heliga gravens kyrka.",h:"Den första böneriktningen"},
    {q:"Vad var det gamla kananeiska namnet på Jerusalem?",o:["Jebus","Jerusalem","Aelia"],f:"Jebus var det ursprungliga kananeiska namnet på Jerusalem, uppkallat efter jebuséerna, en kananeisk folk.",h:"Börjar med bokstaven J"},
    {q:"Vem byggde staden Jerusalem för första gången?",o:["De jebuseiska kananéerna","Romarna","Grekerna"],f:"De jebuseiska kananéerna byggde Jerusalem för 5000 år sedan och gjorde det till en stark fästning.",h:"En gren av kananéerna"},
    {q:"Vilket hav gränsar Palestina i väster?",o:["Medelhavet","Röda havet","Arabiska havet"],f:"Medelhavet ger Palestina en vacker kust på 224 km långt och ett tempererat klimat.",h:"Samma hav som skuggar över Jaffa och Haifa"},
    {q:"Vad är huvudfloden i Palestina?",o:["Jordanfloden","Nilen","Eufrat"],f:"Jordanfloden uppstår från Hermon och mynnar i Döda havet med en längd på 251 km.",h:"Mynnar i Döda havet"},
    {q:"Vad är klimatet i Palestina?",o:["Mediterrpert klimat som är tempererat","Mycket varmt ökenklimtat","Kallt polarklimtat"],f:"Palestinas klimat är varierande: tempererad kust, kalla berg på vintern, varma dalar - hemligheterna till dess jordbruksvälstånd.",h:"Liknar Libanons klimat"},
    {q:"Namnge 3 berömda kananeiska städer som fortfarande existerar?",o:["Jeriko, Jerusalem (Jebus) och Hebron","London, Paris och Rom","Kairo, Bagdad och Damaskus endast"],f:"Jeriko, Jebus (Jerusalem), Hebron, Nablus, Acre, Jaffa, Bethshan, Megiddo - alla är av kananeisk ursprung.",h:"Palestinska städer vi känner idag"},
    {q:"Vad var kananéerna berömda för inom jordbruk?",o:["Att odla vete, oliver och druvor","Odla endast ris","De brydde sig inte om jordbruk"],f:"Kananéerna var de första att plantera olivträd i världen, och olivträdet är en symbol för Palestina än idag.",h:"Tre berömda medelhavsgrödor"},
    {q:"Vad var kananéerna berömda för inom industri?",o:["Tillverka purpurfärg, glas och keramik","Tillverka bilar","Tillverka plast"],f:"Purpur var den dyraste färgen i den antika världen, utvinnad från snäckor och exporterad till kungar.",h:"Gamla dyrbara hantverk"},
    {q:"Vad uppfann kananéerna och gav till världen?",o:["Alfabetet / alfabetisk skrift","Internet","Elektricitet"],f:"Det kananeiska alfabetet (22 bokstäver) är modern för alla alfabeten i världen, inklusive arabiska, hebreiska och latinska.",h:"En uppfinnning som hjälpte mänskligheten att skriva enkelt"},
    {q:"Vilka är de geografiska dragen i Palestina?",o:["Kustslätt, berg, dalar och Negev-öknen","Endast öken","Endast gletscherberg"],f:"På 27 000 km² hittar du alla landskapsformer: kust, berg, dal, öken - Palestina är ett miniatyrkontinent!",h:"Mycket varierande trots liten storlek"},
    {q:"Vad är Palestinas berömda sjö?",o:["Galiléiska sjön (Tiberias)","Victoriasjön","Qarunsjön"],f:"Galiléiska sjön är sötvattens- och vacker, belägen 212 m under havsnivån och matar Jordanfloden.",h:"I norra Palestina"},
    {q:"Vad är Döda havet?",o:["Världens lägsta punkt och saltaste","Ett vanligt hav som Medelhavet","En stor flod"],f:"Döda havet ligger 427 meter under havsnivån, tio gånger saltare än vanligt havsvatten utan fiskar.",h:"Du kan flyta på ytan utan att simma!"},
    {q:"Varför är Palestina jordbruksrikt?",o:["Mångfalden av sitt klimat, terräng och fertil jord","Eftersom det importerar allt","Eftersom det är en öken"],f:"Från Jaffas apelsiner till Hebrons druvor till Galilei oliver - klimatmångfald gjorde Palestina till ett livsmedelsmagasin.",h:"Anledningen är geografisk och naturlig"},
    {q:"Vilket språk talade kananéerna?",o:["Kananeiska semitiska språk, liknar arabiska","Engelska","Kinesiska"],f:"Kananeiska ligger mycket nära arabiska: ord som hus, kung, sol, yam (hav) är fortfarande desamma!",h:"Från samma språkfamilj som arabiska"},
    {q:"Hur var kananeiska hus?",o:["Gjord av lera och sten med trätak","Gjord av järn och glas","Endast tält"],f:"Kananeiska hus var robusta, gjorda av sten och lera med tjocka väggar som skyddade från värme och kyla, och några finns fortfarande!",h:"Naturliga material tillgängliga i bergen"},
    {q:"Vilken var kananéernas religion?",o:["Hedensk, tillbeder Baal och Astarte","Muslimsk","Kristen"],f:"Kananéerna tillbad naturkrafter: Baal guden för regn och Astarte gudinna för fruktbarhet, innan de abrahamitiska religionerna anlände.",h:"Före islam och kristendom"},
    {q:"Vad byggde kananéerna för att försvara sina städer?",o:["Höga väggar och torn som Jericos vägg","Endast vattengravt","De byggde ingenting"],f:"Jericos vägg var 3 meter bred och 7 meter hög, den äldsta och starkaste muren i antik historia.",h:"Jeriko är berömt för sin vägg"},
    {q:"Varför var Palestina eftertraktat av invasörer genom historien?",o:["Dess strategiska läge mellan kontinenter och handelsvägar","Eftersom det är fattig","Eftersom det är en isolerad ö"],f:"Palestina är en bro mellan Asien och Afrika och en port till Egypten, Levanten och Irak - vem som helst som kontrollerar det kontrollerar handeln.",h:"Anledningen är geografisk och ekonomisk"},
    {q:"Vad är den religiösa betydelsen av Palestina?",o:["Vagga för monoteistiska religioner och första böneriktning","Ingen religiös betydelse","Viktigt för endast en religion"],f:"Den innehåller Al-Aqsa den första böneriktningen och tredje heliga platsen, Heliga gravens kyrka, och Abraham-moskén - världens andliga centrum.",h:"Viktigt för muslimer, kristna och judar"},
    {q:"Vad är den historiska betydelsen av Palestina?",o:["En passage för civilisationer och en mötespunkt för handels- och kulturvägar","Ingen passerade genom det","Det var tomt"],f:"Varje armé och civilisation i historien passerade genom Palestina: Siden Road, Spice Route och sjövägar.",h:"Som en stor marknad som alla passerar igenom"},
    {q:"Vilka civilisationer följde kananéerna i Palestina?",o:["Egyptisk, assyrisk, babylonisk, persisk, grekisk, romersk","Endast en civilisation","Inga civilisationer efter"],f:"24 civilisationer följde varandra i Palestina, men kananéerna är ursprunget och grunden, och palestinier idag är deras fortsättning.",h:"Alla antika civilisationer i Mellanöstern"},
    {q:"Varför kallade grekerna kananéerna för fenicier?",o:["Uppkallade efter purpuren (phoinix) de tillverkade och exporterade","Uppkallad efter den mytiska fågeln Fönix endast","Eftersom de bara bodde i Fenisien"],f:"Phoinix på grekiska betyder purpur, eftersom kananéerna hade monopol på produktion av den dyra kungsliga purpurfärgen.",h:"Ordet är grekiska som betyder purpurfärgen"},
    {q:"Hur bevarade kananéerna sin identitet?",o:["Genom att hålla fast vid sin mark, språk, städer och jordbruk","Genom emigration och att överge marken","Genom att assimileras med invasörer"],f:"Trots invasion förblev kananéerna på sin mark, odlande och byggande den - det är vad palestinier gör idag: stadga!",h:"Tänk på ordet stadga"},
    {q:"Vad är beviset på antik civilisation i Jeriko?",o:["Rester av Tell es-Sultan, väggar och stenttorn","Inget bevis","Endast nyare skrifter"],f:"Tell es-Sultan i Jeriko avslöjade hus, väggar och ett stentorn 8 meter högt från 8000 f.Kr.!",h:"En berömd arkeologisk mound"},
    {q:"Vad lär vi oss från kananéerna idag?",o:["Kärlek till mark, arbete, byggande och stadga","Lathet och emigration","Glömska på historia"],f:"Kananéerna lärde oss: marken är heder, den som odlar sin mark kommer inte att svälta, den som bygger sitt hus kommer inte att förvisas.",h:"Positiva värden för studenter"},
    {q:"Vad är palestiniernas relation till kananéerna idag?",o:["En historisk och kulturell fortsättning och ett folk på en mark","Ingen relation","Ett helt olika folk"],f:"DNA-tester bevisar att 90% av palestinier är direkta ättlingar till kananéerna - vi har varit här i 4000 år!",h:"Vi är deras ättlingar"},
    {q:"Varför studerar vi Kanaans historia?",o:["För att känna till våra rötter och historiska rättigheter i Palestina","För underhållning endast","Eftersom det är ett oviktigt ämne"],f:"Den som inte känner sin historia känner inte sina rättigheter. Att studera Kanaan bevisar att Palestina är vårt innan historien ens skrevs!",h:"För att bevisa våra historiska rättigheter"}
  ],
  ru: [
    {q:"Кто был первым народом, жившим в Палестине и построившим ее цивилизацию?",o:["Ханаанеи","Римляне","Турки"],f:"Ханаанеи мигрировали из Аравийского полуострова 4000 лет назад и построили более 200 городов в Палестине.",h:"Их имя начинается с буквы К"},
    {q:"Почему Палестина называлась Землей Ханаана?",o:["В честь ханаанеев, которые ее поселили","В честь горы Ханаан","В честь реки Ханаан"],f:"Земля была названа Ханааном в честь ханаанеев, которые развили ее и сделали зеленым раем.",h:"Имя связано с первыми жителями"},
    {q:"Какой самый древний город в Палестине и мире?",o:["Иерихон","Иерусалим","Газа"],f:"Иерихон - самый древний обитаемый город в истории, построенный ханаанеями и называемый Городом Луны.",h:"Расположен в долине Иордана"},
    {q:"Сколько лет предположительно городу Иерихон?",o:["Около 10 000 лет","Около 1 000 лет","Около 500 лет"],f:"Телль ес-Султан в Иерихоне доказывает его возраст в 10 000 лет и содержит самую древнюю стену в мире.",h:"Намного старше пирамид"},
    {q:"Что означает слово Ханаан?",o:["Низменность и земля пурпура","Высокогорье","Пустынная земля"],f:"Ханаан означает низменность, а также земля пурпура, потому что они были известны производством драгоценного пурпурного краска.",h:"Имеет два значения, связанные с природой"},
    {q:"Где расположена Палестина?",o:["В центре Леванта и на юго-западе Азии","В Северной Африке","В Восточной Европе"],f:"Палестина стратегически расположена между тремя континентами: Азией, Африкой и Европой.",h:"В центре арабского мира"},
    {q:"Какая столица Палестины?",o:["Иерусалим","Рамаллах","Наблус"],f:"Иерусалим - вечная столица Палестины, содержащая мечеть Аль-Акса и Церковь Святого Гроба.",h:"Первое направление молитвы"},
    {q:"Какое было древнее ханаанейское название Иерусалима?",o:["Иебус","Иерусалим","Элия"],f:"Иебус было оригинальное ханаанейское название Иерусалима, названное в честь иевусеев, ханаанейского народа.",h:"Начинается с буквы И"},
    {q:"Кто первым построил город Иерусалим?",o:["Иевусеи-ханаанеи","Римляне","Греки"],f:"Иевусеи-ханаанеи построили Иерусалим 5000 лет назад и сделали его мощной крепостью.",h:"Ветвь ханаанеев"},
    {q:"Какое море граничит с Палестиной на западе?",o:["Средиземное море","Красное море","Аравийское море"],f:"Средиземное море дает Палестине прекрасный берег длиной 224 км и умеренный климат.",h:"То же море, что омывает Яффу и Хайфу"},
    {q:"Какая главная река в Палестине?",o:["Река Иордан","Нил","Евфрат"],f:"Иордан берет начало на горе Хермон и впадает в Мертвое море с длиной 251 км.",h:"Впадает в Мертвое море"},
    {q:"Какой климат в Палестине?",o:["Средиземноморский, умеренный климат","Очень жаркий пустынный климат","Холодный полярный климат"],f:"Климат Палестины разнообразен: умеренное побережье, холодные горы зимой, жаркие долины - секрет ее сельскохозяйственного богатства.",h:"Как климат Ливана"},
    {q:"Назовите 3 знаменитых ханаанейских города, которые существуют?",o:["Иерихон, Иерусалим (Иебус) и Хеврон","Лондон, Париж и Рим","Каир, Багдад и Дамаск только"],f:"Иерихон, Иебус (Иерусалим), Хеврон, Наблус, Акка, Яффа, Бефсан, Мегиддо - все ханаанейского происхождения.",h:"Палестинские города, которые мы знаем"},
    {q:"Чем были известны ханаанеи в земледелии?",o:["Выращиванием пшеницы, оливок и винограда","Выращиванием только риса","Они не занимались земледелием"],f:"Ханаанеи были первыми, кто посадил оливковые деревья в мире, и оливка является символом Палестины до сегодня.",h:"Три известных средиземноморских культуры"},
    {q:"Чем были известны ханаанеи в промышленности?",o:["Производством пурпура, стекла и керамики","Производством автомобилей","Производством пластика"],f:"Пурпур был самым дорогим краской в древнем мире, извлекаемым из раковин и экспортируемым королям.",h:"Древние драгоценные ремесла"},
    {q:"Что изобрели ханаанеи и дали миру?",o:["Алфавит / алфавитное письмо","Интернет","Электричество"],f:"Ханаанейский алфавит (22 буквы) - мать всех алфавитов в мире, включая арабский, иврит и латинский.",h:"Изобретение, помогшее человечеству писать легко"},
    {q:"Каковы географические особенности Палестины?",o:["Прибрежные равнины, горы, долины и пустыня Негев","Только пустыня","Только ледниковые горы"],f:"На 27 000 км² вы найдете все рельефы: берег, гору, долину, пустыню - Палестина - миниатюрный континент!",h:"Очень разнообразна несмотря на малый размер"},
    {q:"Какое известное озеро в Палестине?",o:["Озеро Тивериада (Галилейское)","Озеро Виктория","Озеро Карун"],f:"Озеро Тивериада пресное и прекрасное, расположено на 212 м ниже уровня моря и питает реку Иордан.",h:"В северной Палестине"},
    {q:"Что такое Мертвое море?",o:["Самая низкая точка на земле и самая соленая","Обычное море как Средиземное","Большая река"],f:"Мертвое море на 427 метров ниже уровня моря, в десять раз соленее обычной морской воды без рыб.",h:"Можешь плавать на его поверхности без плавания!"},
    {q:"Почему Палестина богата в сельском хозяйстве?",o:["Разнообразие климата, рельефа и плодородной почвы","Потому что все импортирует","Потому что это пустыня"],f:"От апельсинов Яффы к винограду Хеврона к оливкам Галилеи - климатическое разнообразие сделало Палестину хранилищем продовольствия.",h:"Причина географическая и естественная"},
    {q:"На каком языке говорили ханаанеи?",o:["На ханаанейском семитском языке, похож на арабский","На английском","На китайском"],f:"Ханаанейский очень близок к арабскому: слова как дом, король, солнце, ям (море) все еще одинаковые!",h:"Из той же языковой семьи, что и арабский"},
    {q:"Как были дома ханаанеев?",o:["Из глины и камня с деревянными крышами","Из железа и стекла","Только палатки"],f:"Ханаанейские дома были крепкие, из камня и глины с толстыми стенами, защищающими от жары и холода, и некоторые все еще стоят!",h:"Природные материалы, доступные в горах"},
    {q:"Какая была религия ханаанеев?",o:["Языческая, поклонялась Баалу и Астарте","Мусульманская","Христианская"],f:"Ханаанеи поклонялись силам природы: Баал бог дождя и Астарта богиня плодородия, до прихода авраамических религий.",h:"До ислама и христианства"},
    {q:"Что строили ханаанеи для защиты своих городов?",o:["Высокие стены и башни как стена Иерихона","Только водяные рвы","Они ничего не строили"],f:"Стена Иерихона была 3 метра в ширину и 7 метров в высоту, самая старая и самая крепкая стена в древней истории.",h:"Иерихон известен своей стеной"},
    {q:"Почему Палестина была желаема захватчиками через историю?",o:["Его стратегическое положение между континентами и торговыми путями","Потому что она бедная","Потому что это изолированный остров"],f:"Палестина - мост между Азией и Африкой и ворота в Египет, Левант и Ирак - кто ее контролирует, контролирует торговлю.",h:"Причина географическая и экономическая"},
    {q:"Какова религиозная важность Палестины?",o:["Колыбель монотеистических религий и первое направление молитвы","Без религиозной важности","Важна только одной религии"],f:"Она содержит Аль-Акса первое направление молитвы и третье святое место, Церковь Святого Гроба, мечеть Ибрахима - духовный центр мира.",h:"Важна мусульманам, христианам и евреям"},
    {q:"Какова историческая важность Палестины?",o:["Проход для цивилизаций и встреча торговых и культурных путей","Никто не проходил через нее","Она была пуста"],f:"Каждая армия и цивилизация в истории прошла через Палестину: Шелковый путь, путь специй и морские пути.",h:"Как большой рынок, через который проходят все"},
    {q:"Какие цивилизации сменили ханаанеев в Палестине?",o:["Египетская, ассирийская, вавилонская, персидская, греческая, римская","Только одна цивилизация","После них не было цивилизаций"],f:"24 цивилизации сменяли друг друга в Палестине, но ханаанеи - это происхождение и основание, и палестинцы сегодня - их продолжение.",h:"Все древние цивилизации Ближнего Востока"},
    {q:"Почему греки называли ханаанеев финикийцами?",o:["По названию пурпура (phoinix), который они производили и экспортировали","По названию мифической птицы Феникс только","Потому что они жили только в Финикии"],f:"Phoinix по-гречески означает пурпур, потому что ханаанеи имели монополию на производство драгоценного королевского пурпурного краска.",h:"Слово греческое, означает пурпурный цвет"},
    {q:"Как ханаанеи сохранили свою идентичность?",o:["Прилежанием к своей земле, языку, городам и земледелию","Путем миграции и отказа от земли","Путем ассимиляции с захватчиками"],f:"Несмотря на захват, ханаанеи остались на своей земле, возделывая и строя ее - это то, что делают палестинцы сегодня: стойкость!",h:"Думайте о слове стойкость"},
    {q:"Какие доказательства древней цивилизации в Иерихоне?",o:["Остатки Телль ес-Султана, стены и каменные башни","Нет доказательств","Только недавние письма"],f:"Телль ес-Султан в Иерихоне открыл дома, стены и каменную башню высотой 8 метров из 8000 года до нашей эры!",h:"Знаменитый археологический холм"},
    {q:"Что мы учимся у ханаанеев сегодня?",o:["Любовь к земле, работе, строительству и стойкости","Лень и миграцию","Забывание истории"],f:"Ханаанеи учили нас: земля - честь, кто возделывает свою землю, не голодает, кто строит свой дом, не будет вытеснен.",h:"Позитивные ценности для студентов"},
    {q:"Какова связь палестинцев сегодня с ханаанеями?",o:["Историческое и культурное продолжение и один народ на одной земле","Нет связи","Совершенно другой народ"],f:"Тесты ДНК доказывают, что 90% палестинцев - прямые потомки ханаанеев - мы здесь уже 4000 лет!",h:"Мы их потомки"},
    {q:"Почему мы изучаем историю Ханаана?",o:["Чтобы узнать свои корни и исторические права в Палестине","Только для развлечения","Потому что это неважный предмет"],f:"Кто не знает свою историю, не знает свои права. Изучение Ханаана доказывает, что Палестина наша, еще до того, как была написана история!",h:"Доказать свои исторические права"}
  ],
  zh: [
    {q:"谁是第一个居住在巴勒斯坦并建立其文明的民族?",o:["迦南人","罗马人","奥斯曼人"],f:"迦南人在4000年前从阿拉伯半岛迁移过来，在巴勒斯坦建立了200多个城市。",h:"他们的名字以字母C开头"},
    {q:"为什么巴勒斯坦被称为迦南地?",o:["以居住在那里的迦南人命名","以迦南山命名","以迦南河命名"],f:"该地被命名为迦南，以纪念开发它并将其变成绿色天堂的迦南人。",h:"这个名字与最初的居民有关"},
    {q:"巴勒斯坦和世界上最古老的城市是什么?",o:["耶利哥","耶路撒冷","加沙"],f:"耶利哥是历史上最古老的有人居住的城市，由迦南人建立，被称为月亮之城。",h:"位于约旦河谷"},
    {q:"耶利哥城的年龄估计是多少?",o:["约10000年","约1000年","约500年"],f:"耶利哥的特尔·苏尔丹遗址证明它已有10000年的历史，是世界上最古老的城墙。",h:"比金字塔古老得多"},
    {q:"迦南这个词是什么意思?",o:["低地和紫色之地","高地","沙漠之地"],f:"迦南意为低地，也被称为紫色之地，因为他们以生产珍贵的紫色染料而闻名。",h:"它有两个与自然相关的含义"},
    {q:"巴勒斯坦位于何处?",o:["在凡特和西亚西南部的中心","在北非","在东欧"],f:"巴勒斯坦的位置很有策略性，位于三个大陆之间：亚洲、非洲和欧洲。",h:"在阿拉伯世界的中心"},
    {q:"巴勒斯坦的首都是什么?",o:["耶路撒冷","拉姆真主的真主","纳布卢斯"],f:"耶路撒冷是巴勒斯坦永恒的首都，拥有阿克萨清真寺和圣墓教堂。",h:"第一个祈祷方向"},
    {q:"耶路撒冷的古代迦南名称是什么?",o:["耶布斯","耶路撒冷","埃利亚"],f:"耶布斯是耶路撒冷的原始迦南名称，以定居在那里的耶布斯人命名。",h:"以字母J开头"},
    {q:"谁第一次建造了耶路撒冷城?",o:["耶布斯人迦南人","罗马人","希腊人"],f:"耶布斯人迦南人在5000年前建造了耶路撒冷，并使其成为一个强大的堡垒。",h:"迦南人的一个分支"},
    {q:"哪片海洋在西边与巴勒斯坦接壤?",o:["地中海","红海","阿拉伯海"],f:"地中海为巴勒斯坦提供了224公里长的美丽海岸线和温和的气候。",h:"同一片海洋俯瞰雅法和海法"},
    {q:"巴勒斯坦的主要河流是什么?",o:["约旦河","尼罗河","幼发拉底河"],f:"约旦河发源于赫尔蒙山，流入死海，长度为251公里。",h:"流入死海"},
    {q:"巴勒斯坦的气候是什么?",o:["地中海气候温和","非常炎热的沙漠气候","寒冷的两极气候"],f:"巴勒斯坦的气候多样化：温和的海岸、冬季寒冷的山脉、炎热的山谷——这是其农业财富的秘密。",h:"如黎巴嫩气候"},
    {q:"列举3个仍然存在的著名迦南城市?",o:["耶利哥、耶路撒冷（耶布斯）和希伯伦","伦敦、巴黎和罗马","开罗、巴格达和大马士革仅"],f:"耶利哥、耶布斯（耶路撒冷）、希伯伦、纳布卢斯、阿卡、雅法、伯笃生、麦吉多——都起源于迦南人。",h:"我们今天所知的巴勒斯坦城市"},
    {q:"迦南人因农业而闻名什么?",o:["种植小麦、橄榄和葡萄","仅种植米","他们不关心农业"],f:"迦南人是世界上第一个种植橄榄树的人，橄榄树至今仍是巴勒斯坦的象征。",h:"三种著名的地中海作物"},
    {q:"迦南人因工业而闻名什么?",o:["生产紫色染料、玻璃和陶器","生产汽车","生产塑料"],f:"紫色是古代世界最贵的染料，从贝壳中提取并出口给国王。",h:"古代珍贵的手工艺"},
    {q:"迦南人发明了什么并奉献给世界?",o:["字母/字母文字","互联网","电力"],f:"迦南字母表（22个字母）是世界上所有字母的母亲，包括阿拉伯语、希伯来语和拉丁语。",h:"帮助人类轻松写字的发明"},
    {q:"巴勒斯坦的地理特征是什么?",o:["沿海平原、山脉、山谷和内盖夫沙漠","仅沙漠","仅冰川山脉"],f:"在27000平方公里内，您可以找到所有地形：海岸、山脉、山谷、沙漠——巴勒斯坦是一个缩小版大陆！",h:"尽管面积很小但非常多样化"},
    {q:"巴勒斯坦著名的湖泊是什么?",o:["提比利亚湖（加利利海）","维多利亚湖","卡伦湖"],f:"提比利亚湖是淡水湖，位于海平面以下212米，为约旦河补充水源。",h:"在巴勒斯坦北部"},
    {q:"死海是什么?",o:["地球上最低点和最咸的","普通海洋如地中海","大河"],f:"死海位于海平面以下427米，咸度是普通海水的十倍，没有鱼类生活。",h:"你可以在不游泳的情况下漂浮！"},
    {q:"巴勒斯坦为什么农业丰富?",o:["气候、地形和肥沃土壤的多样性","因为它进口一切","因为它是沙漠"],f:"从雅法的橙子到希伯伦的葡萄再到加利利的橄榄——气候多样性使巴勒斯坦成为粮仓。",h:"原因是地理和自然的"},
    {q:"迦南人说什么语言?",o:["迦南闪含语言，类似于阿拉伯语","英语","中文"],f:"迦南语与阿拉伯语非常接近：词汇如房屋、国王、太阳、海洋至今仍是一样的！",h:"来自与阿拉伯语相同的语言家族"},
    {q:"迦南人的房屋是什么样的?",o:["用粘土和石头制成，木制屋顶","用铁和玻璃制成","仅帐篷"],f:"迦南人的房屋很坚固，用石头和粘土制成，厚墙保护免受炎热和寒冷，至今仍有一些存在！",h:"山上可用的天然材料"},
    {q:"迦南人的宗教是什么?",o:["异教，崇拜巴力和阿斯塔蒂","伊斯兰教","基督教"],f:"迦南人崇拜自然力量：巴力（雨之神）和阿斯塔蒂（丰饶女神），在一神教到来之前。",h:"伊斯兰教和基督教之前"},
    {q:"迦南人为了保卫城市而建造了什么?",o:["高墙和塔楼，如耶利哥城墙","仅水壕","他们什么都没建造"],f:"耶利哥城墙宽3米，高7米，是古代历史中最古老、最坚固的城墙。",h:"耶利哥以其城墙而闻名"},
    {q:"为什么整个历史上巴勒斯坦受到入侵者觊觎?",o:["其在大陆间的战略位置和贸易路线","因为它很贫穷","因为它是一个孤立的岛屿"],f:"巴勒斯坦是亚洲和非洲之间的桥梁，以及埃及、黎凡特和伊拉克的门户——谁控制它就控制贸易。",h:"原因是地理和经济的"},
    {q:"巴勒斯坦的宗教重要性是什么?",o:["一神教的摇篮和第一个祈祷方向","没有宗教重要性","仅对一个宗教重要"],f:"它包含阿克萨（第一个祈祷方向）和第三圣地、圣墓教堂、易卜拉欣清真寺——世界精神中心。",h:"对穆斯林、基督徒和犹太人重要"},
    {q:"巴勒斯坦的历史重要性是什么?",o:["文明的通道和贸易文化路线的汇合点","没有人通过它","它是空的"],f:"历史上的每支军队和每种文明都经过巴勒斯坦：丝绸之路、香料之路和海路。",h:"像一个大市场，每个人都经过"},
    {q:"哪些文明在巴勒斯坦取代了迦南人?",o:["埃及、亚述、巴比伦、波斯、希腊、罗马","仅一个文明","之后没有文明"],f:"24个文明在巴勒斯坦相继更替，但迦南人是起源和基础，今天的巴勒斯坦人是他们的延续。",h:"中东所有古代文明"},
    {q:"为什么希腊人把迦南人称为腓尼基人?",o:["以他们生产和出口的紫色(phoinix)命名","仅以神话鸟凤凰命名","因为他们仅住在腓尼基"],f:"腓尼基在希腊语中意为紫色，因为迦南人垄断了生产珍贵的皇家紫色染料。",h:"这个词是希腊语，意为紫色"},
    {q:"迦南人如何保留了他们的身份?",o:["通过坚守土地、语言、城市和农业","通过移民和放弃土地","通过与入侵者同化"],f:"尽管入侵，迦南人仍留在他们的土地上，耕种和建设它——这就是巴勒斯坦人今天所做的：坚持不懈！",h:"想想坚持不懈这个词"},
    {q:"耶利哥古代文明的证据是什么?",o:["特尔·苏尔丹的遗迹、城墙和石塔","没有证据","仅最近的文献"],f:"耶利哥的特尔·苏尔丹揭示了来自公元前8000年的房屋、城墙和8米高的石塔！",h:"著名的考古遗址"},
    {q:"我们今天从迦南人学到了什么?",o:["对土地、工作、建设和坚持不懈的热爱","懒惰和移民","遗忘历史"],f:"迦南人教会我们：土地是荣誉，谁耕种他的土地就不会挨饿，谁建造他的房子就不会被驱逐。",h:"学生的积极价值观"},
    {q:"今天巴勒斯坦人与迦南人的关系是什么?",o:["历史文化延续和同一土地上的同一民族","没有关系","完全不同的民族"],f:"DNA测试证明90%的巴勒斯坦人是迦南人的直系后代——我们已在这里4000年了！",h:"我们是他们的后代"},
    {q:"为什么我们研究迦南的历史?",o:["了解我们在巴勒斯坦的根源和历史权利","仅为了娱乐","因为这是一个不重要的主题"],f:"不了解自己历史的人不了解自己的权利。研究迦南证明巴勒斯坦是我们的，甚至在历史被写下之前！",h:"证明我们的历史权利"}
  ],
  hi: [
    {q:"फिलिस्तीन में बसने वाली और अपनी सभ्यता बनाने वाली पहली जनता कौन थी?",o:["कनानी","रोमन","उस्मानिया"],f:"कनानी 4000 साल पहले अरब प्रायद्वीप से पलायन करके फिलिस्तीन में 200 से अधिक शहर बसाए।",h:"उनका नाम अक्षर C से शुरू होता है"},
    {q:"फिलिस्तीन को कनान की भूमि क्यों कहा जाता है?",o:["वहां बसने वाले कनानियों के नाम पर","कनान पर्वत के नाम पर","कनान नदी के नाम पर"],f:"इस भूमि को कनान नाम दिया गया था उन कनानियों के नाम पर जिन्होंने इसे विकसित किया और हरी स्वर्ग बनाया।",h:"नाम पहली आबादी से संबंधित है"},
    {q:"फिलिस्तीन और दुनिया का सबसे पुराना शहर कौन सा है?",o:["यरीहो","यरूशलेम","गाजा"],f:"यरीहो इतिहास में सबसे पुराना बसा हुआ शहर है, कनानियों द्वारा निर्मित और चंद्रमा का शहर कहा जाता है।",h:"जॉर्डन की घाटी में स्थित है"},
    {q:"यरीहो शहर की अनुमानित आयु कितनी है?",o:["लगभग 10,000 साल","लगभग 1,000 साल","लगभग 500 साल"],f:"यरीहो के तेल-एस-सुल्तान में साक्ष्य से पता चलता है कि यह 10,000 साल पुराना है और दुनिया की सबसे पुरानी दीवार है।",h:"पिरामिडों से कहीं अधिक प्राचीन है"},
    {q:"कनान शब्द का क्या अर्थ है?",o:["निचली भूमि और बैंगनी रंग की भूमि","ऊंची भूमि","मरुस्थल भूमि"],f:"कनान का अर्थ है निचली भूमि, और यह बैंगनी भूमि भी कहलाती है क्योंकि वह कीमती बैंगनी रंग के लिए प्रसिद्ध थे।",h:"इसके दो अर्थ प्रकृति से संबंधित हैं"},
    {q:"फिलिस्तीन कहां स्थित है?",o:["लेवांत के दिल में और पश्चिम एशिया में","उत्तरी अफ्रीका में","पूर्वी यूरोप में"],f:"फिलिस्तीन का स्थान रणनीतिक है, तीन महाद्वीपों के बीच स्थित है: एशिया, अफ्रीका और यूरोप।",h:"अरब दुनिया के दिल में"},
    {q:"फिलिस्तीन की राजधानी क्या है?",o:["यरूशलेम","रामल्लाह","नाबुलस"],f:"यरूशलेम फिलिस्तीन की शाश्वत राजधानी है, अल-अक्सा मस्जिद और पवित्र सेपुल्कर चर्च है।",h:"प्रार्थना की पहली दिशा"},
    {q:"यरूशलेम का प्राचीन कनानी नाम क्या था?",o:["येबूस","यरूशलेम","एलिया"],f:"येबूस यरूशलेम का मूल कनानी नाम था, जो येबूसियों के नाम पर रखा गया था जो यहां बसते थे।",h:"अक्षर Y से शुरू होता है"},
    {q:"पहली बार यरूशलेम शहर किसने बनाया था?",o:["येबूसी कनानी","रोमन","यूनानी"],f:"येबूसी कनानियों ने 5000 साल पहले यरूशलेम बनाया और इसे एक दुर्गम दुर्ग बनाया।",h:"कनानियों की एक शाखा"},
    {q:"कौन सा समुद्र पश्चिम में फिलिस्तीन से लगता है?",o:["भूमध्य सागर","लाल सागर","अरब सागर"],f:"भूमध्य सागर फिलिस्तीन को 224 किमी लंबी सुंदर समुद्र तटीय रेखा और समशीतोष्ण जलवायु देता है।",h:"वही समुद्र जो याफा और हैफा को निहारता है"},
    {q:"फिलिस्तीन में मुख्य नदी कौन सी है?",o:["जॉर्डन नदी","नील नदी","यूफ्रेट्स नदी"],f:"जॉर्डन नदी हरमोन पर्वत से उत्पन्न होती है और मृत सागर में गिरती है, 251 किमी लंबी है।",h:"मृत सागर में बहती है"},
    {q:"फिलिस्तीन की जलवायु क्या है?",o:["भूमध्यसागरीय जलवायु जो समशीतोष्ण है","बहुत गर्म मरुस्थलीय जलवायु","ठंडी ध्रुवीय जलवायु"],f:"फिलिस्तीन की जलवायु विविध है: समशीतोष्ण तट, सर्दियों में ठंडे पहाड़, गर्म घाटियां - यह कृषि समृद्धि का रहस्य है।",h:"लेबनान की जलवायु जैसी"},
    {q:"3 प्रसिद्ध कनानी शहरों का नाम बताएं जो अभी भी मौजूद हैं?",o:["यरीहो, यरूशलेम (येबूस) और हेब्रॉन","लंदन, पेरिस और रोम","काहिरा, बगदाद और दमिश्क केवल"],f:"यरीहो, येबूस (यरूशलेम), हेब्रॉन, नाबुलस, एक्का, याफा, बेथशान, मेगिडो - सभी कनानी मूल के हैं।",h:"आज की फिलिस्तीनी शहरें"},
    {q:"कनानी कृषि में किस के लिए प्रसिद्ध थे?",o:["गेहूं, जैतून और अंगूर की खेती","केवल चावल की खेती","वे कृषि की चिंता नहीं करते थे"],f:"कनानी दुनिया में जैतून के पेड़ लगाने वाले पहले व्यक्ति थे, और जैतून का पेड़ आज भी फिलिस्तीन का प्रतीक है।",h:"तीन प्रसिद्ध भूमध्यसागरीय फसलें"},
    {q:"कनानी उद्योग में किस के लिए प्रसिद्ध थे?",o:["बैंगनी रंग, कांच और मिट्टी के बर्तन बनाना","कारों का निर्माण","प्लास्टिक का निर्माण"],f:"बैंगनी प्राचीन दुनिया में सबसे महंगा रंग था, शंख से निकाला जाता था और राजाओं को निर्यात किया जाता था।",h:"प्राचीन बहुमूल्य कारीगरी"},
    {q:"कनानियों ने क्या आविष्कार किया और दुनिया को दिया?",o:["वर्णमाला / वर्णमाला लिपि","इंटरनेट","विद्युत"],f:"कनानी वर्णमाला (22 अक्षर) दुनिया में सभी वर्णमालाओं की माता है, जिसमें अरबी, हिब्रू और लैटिन शामिल हैं।",h:"एक आविष्कार जिसने मानवता को आसानी से लिखने में मदद की"},
    {q:"फिलिस्तीन की भौगोलिक विशेषताएं क्या हैं?",o:["तटीय मैदान, पहाड़, घाटियां और नेगेव रेगिस्तान","केवल रेगिस्तान","केवल हिमनद पर्वत"],f:"27,000 वर्ग किमी में आप सभी भूभाग पाते हैं: तट, पर्वत, घाटी, रेगिस्तान - फिलिस्तीन एक लघु महाद्वीप है!",h:"अपने छोटे आकार के बावजूद बहुत विविध"},
    {q:"फिलिस्तीन की प्रसिद्ध झील क्या है?",o:["तिबेरिया झील (गलील सागर)","विक्टोरिया झील","कारून झील"],f:"तिबेरिया झील मीठे पानी की है और सुंदर है, समुद्र तल से 212 मीटर नीचे स्थित है और जॉर्डन नदी को पोषण देती है।",h:"उत्तरी फिलिस्तीन में"},
    {q:"मृत सागर क्या है?",o:["पृथ्वी पर सबसे निचला बिंदु और सबसे नमकीन","साधारण समुद्र जैसे भूमध्य सागर","बड़ी नदी"],f:"मृत सागर समुद्र तल से 427 मीटर नीचे है, सामान्य समुद्री पानी से दस गुना अधिक नमकीन और इसमें कोई मछली नहीं है।",h:"आप बिना तैराकी के इसकी सतह पर तैर सकते हैं!"},
    {q:"फिलिस्तीन कृषि में समृद्ध क्यों है?",o:["अपनी जलवायु, भूभाग और उपजाऊ मिट्टी की विविधता","क्योंकि यह सब कुछ आयात करता है","क्योंकि यह एक रेगिस्तान है"],f:"याफा के संतरों से लेकर हेब्रॉन की अंगूरों से लेकर गलील की जैतून तक - जलवायु विविधता ने फिलिस्तीन को अनाज का कटोरा बना दिया।",h:"कारण भौगोलिक और प्राकृतिक है"},
    {q:"कनानी किस भाषा बोलते थे?",o:["कनानी सेमिटिक भाषा, अरबी के समान","अंग्रेज़ी","चीनी"],f:"कनानी अरबी के बहुत करीब है: घर, राजा, सूरज, यम (समुद्र) जैसे शब्द अभी भी समान हैं!",h:"अरबी के समान भाषा परिवार से"},
    {q:"कनानी के घर कैसे थे?",o:["मिट्टी और पत्थर से लकड़ी की छत के साथ बने","लोहे और कांच से बने","केवल तम्बू"],f:"कनानी के घर मजबूत थे, पत्थर और मिट्टी से बने, मोटी दीवारों के साथ जो गर्मी और ठंड से बचाती थीं, और कुछ अभी भी खड़े हैं!",h:"पहाड़ों में उपलब्ध प्राकृतिक सामग्री"},
    {q:"कनानियों का धर्म क्या था?",o:["मूर्तिपूजक, बाल और अस्तर्ते की पूजा करते थे","मुस्लिम","ईसाई"],f:"कनानी प्रकृति की शक्तियों की पूजा करते थे: बाल वर्षा का देवता और अस्तर्ते उर्वरता की देवी, अब्राहमी धर्मों के आगमन से पहले।",h:"इस्लाम और ईसाई धर्म से पहले"},
    {q:"कनानियों ने अपने शहरों की रक्षा के लिए क्या बनाया?",o:["ऊंची दीवारें और टावर जैसे यरीहो की दीवार","केवल जल खाई","उन्होंने कुछ नहीं बनाया"],f:"यरीहो की दीवार 3 मीटर चौड़ी और 7 मीटर ऊंची थी, प्राचीन इतिहास में सबसे पुरानी और सबसे मजबूत दीवार।",h:"यरीहो अपनी दीवार के लिए प्रसिद्ध है"},
    {q:"पूरे इतिहास में फिलिस्तीन पर हमलावर क्यों हमला करते थे?",o:["महाद्वीपों के बीच इसकी रणनीतिक स्थिति और व्यापार मार्गों के कारण","क्योंकि यह गरीब है","क्योंकि यह एक अलग द्वीप है"],f:"फिलिस्तीन एशिया और अफ्रीका के बीच एक पुल है, और मिस्र, लेवांत और इराक का प्रवेश द्वार है - जो इसे नियंत्रित करता है वह व्यापार को नियंत्रित करता है।",h:"कारण भौगोलिक और आर्थिक है"},
    {q:"फिलिस्तीन का धार्मिक महत्व क्या है?",o:["एकेश्वरवादी धर्मों का पालना और प्रार्थना की पहली दिशा","कोई धार्मिक महत्व नहीं","केवल एक धर्म के लिए महत्वपूर्ण"],f:"इसमें अल-अक्सा (प्रार्थना की पहली दिशा) और तीसरा पवित्र स्थान, पवित्र सेपुल्कर चर्च, इब्राहिम मस्जिद है - दुनिया का आध्यात्मिक केंद्र।",h:"मुसलमानों, ईसाइयों और यहूदियों के लिए महत्वपूर्ण"},
    {q:"फिलिस्तीन का ऐतिहासिक महत्व क्या है?",o:["सभ्यताओं के लिए एक मार्ग और व्यापार सांस्कृतिक मार्गों का मिलन बिंदु","कोई भी इसे नहीं भेदता था","यह खाली था"],f:"इतिहास में हर सेना और सभ्यता फिलिस्तीन से होकर गई: रेशम मार्ग, मसाला मार्ग और समुद्री मार्ग।",h:"एक बड़ा बाजार जिसे सभी पार करते हैं"},
    {q:"फिलिस्तीन में कनानियों के बाद कौन सी सभ्यताओं का आगमन हुआ?",o:["मिस्री, असीरियन, बेबीलोन, फारसी, यूनानी, रोमन","केवल एक सभ्यता","उनके बाद कोई सभ्यता नहीं"],f:"फिलिस्तीन में 24 सभ्यताएं एक दूसरे का स्थान लेती थीं, लेकिन कनानी उत्पत्ति और आधार हैं, और आज के फिलिस्तीनी उनका जारी रूप हैं।",h:"मध्य पूर्व की सभी प्राचीन सभ्यताएं"},
    {q:"यूनानियों ने कनानियों को फेनिशियन क्यों कहा?",o:["उन्होंने जो बैंगनी (phoinix) बनाया और निर्यात किया उसके नाम पर","केवल मिथोलॉजिकल बर्ड फीनिक्स के नाम पर","क्योंकि वे केवल फेनिशिया में रहते थे"],f:"Phoinix यूनानी में बैंगनी रंग का अर्थ है, क्योंकि कनानियों ने कीमती शाही बैंगनी रंग के उत्पादन पर एकाधिकार किया।",h:"शब्द यूनानी है जिसका अर्थ बैंगनी रंग है"},
    {q:"कनानियों ने अपनी पहचान को कैसे संरक्षित किया?",o:["अपनी भूमि, भाषा, शहरों और कृषि से जुड़े रहकर","पलायन और भूमि को छोड़कर","आक्रमणकारियों के साथ आत्मसात हो गए"],f:"आक्रमण के बावजूद, कनानी अपनी भूमि पर रहे, इसे खेत और बनाया - यह वही है जो आज फिलिस्तीनी करते हैं: दृढ़ता!",h:"दृढ़ता शब्द के बारे में सोचें"},
    {q:"यरीहो में प्राचीन सभ्यता के साक्ष्य क्या हैं?",o:["तेल-एस-सुल्तान के अवशेष, दीवारें और पत्थर के टावर","कोई साक्ष्य नहीं","केवल हाल ही की लिखावट"],f:"यरीहो के तेल-एस-सुल्तान में 8000 ईसा पूर्व से 8 मीटर ऊंचा पत्थर का टावर, दीवारें और घर मिले!",h:"एक प्रसिद्ध पुरातात्विक टेल"},
    {q:"हम आज कनानियों से क्या सीखते हैं?",o:["भूमि, कार्य, निर्माण और दृढ़ता के प्रति प्रेम","आलस्य और पलायन","इतिहास की भुलक्कड़ता"],f:"कनानियों ने हमें सिखाया: भूमि सम्मान है, जो अपनी भूमि को खेती करता है वह भूखा नहीं रहेगा, जो अपना घर बनाता है वह विस्थापित नहीं होगा।",h:"छात्रों के लिए सकारात्मक मूल्य"},
    {q:"आज फिलिस्तीनियों का कनानियों से क्या संबंध है?",o:["ऐतिहासिक सांस्कृतिक निरंतरता और एक भूमि पर एक जनता","कोई संबंध नहीं","बिल्कुल अलग जनता"],f:"डीएनए परीक्षण साबित करते हैं कि 90% फिलिस्तीनी कनानियों के सीधे वंशज हैं - हम यहां 4000 साल से हैं!",h:"हम उनके वंशज हैं"},
    {q:"हम कनान का इतिहास क्यों पढ़ते हैं?",o:["अपनी जड़ों और फिलिस्तीन में ऐतिहासिक अधिकारों को जानने के लिए","केवल मनोरंजन के लिए","क्योंकि यह एक महत्वहीन विषय है"],f:"जो अपना इतिहास नहीं जानता वह अपने अधिकार नहीं जानता। कनान का अध्ययन साबित करता है कि फिलिस्तीन हमारा है, इतिहास लिखे जाने से भी पहले!",h:"अपने ऐतिहासिक अधिकार साबित करने के लिए"}
  ]
};

/* دالة للحصول على السؤال المترجم */
function getTranslatedQuestions(langCode = 'ar') {
  const lang = QUESTIONS_I18N[langCode] || QUESTIONS_I18N.ar;
  return lang.map((item, index) => ({
    id: index + 1,
    level: index < 12 ? 1 : (index < 24 ? 2 : 3),
    q: item.q,
    options: item.o,
    correct: 0,
    fact: item.f,
    hint: item.h
  }));
}

